export const getUpdateCatalogItemUrl = (id: string,) => {




  return `/api/catalog/${id}`
}

/**
 * @summary Update a price catalog item
 */
export const updateCatalogItem = async (id: string,
    updateCatalogItemBody: UpdateCatalogItemBody, options?: Parameters<typeof customFetch>[1]): Promise<CatalogItem> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(Array.from(h as unknown as Iterable<[string, string]>));
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<CatalogItem>(getUpdateCatalogItemUrl(id),
  {
    ...options,
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(updateCatalogItemBody)
  }
);}





